DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='voertuig_open_punten'; d:=replace(d,'concat_ws('' · '', w.description, w.part)','concat_ws('' · '', w.description, w.part, CASE WHEN jsonb_typeof(w.parts)=''array'' THEN (SELECT string_agg(x,'' · '') FROM jsonb_array_elements_text(w.parts) a(x)) END)'); d:=replace(d,'concat_ws('' · '',w.description,w.part)','concat_ws('' · '',w.description,w.part,CASE WHEN jsonb_typeof(w.parts)=''array'' THEN (SELECT string_agg(x,'' · '') FROM jsonb_array_elements_text(w.parts) a(x)) END)'); d:=replace(d,'me.details->>''deliveryAppointmentDate''','(SELECT a.starttime FROM public.appointments a WHERE a.id::text=me.details->>''deliveryAppointmentId'')'); d:=replace(d,'''voltooid'',''geannuleerd'',''completed'',''cancelled''','''voltooid'',''geannuleerd'',''completed'',''cancelled'',''afgerond'',''done'''); EXECUTE d; END $$;